// Demo: Priority Queue Shedding — priority queue shedding under pressure
var q=[];for(var i=0;i<2;i++){q.push({p:(i*13+1)%3,ms:10+((i*29)%90)});}
q.sort(function(a,b){return a.p-b.p;});
var budget=2*10,shed=0,kept=0;
q.forEach(function(r){if(budget-r.ms>=0&&r.p<2){budget-=r.ms;kept++;}else{shed++;}});
console.log('technique: Priority Queue Shedding');console.log('queued: '+q.length+', kept: '+kept+', shed: '+shed);
console.log('policy: low-priority work shed first, critical work preserved');

// Demo: Circuit Breaker Tripping — token bucket admission over 8 requests
var tokens=15%50+10,rate=5,reqs=[],now=0;
for(var i=0;i<8;i++){now+=((i*37+2)%40)/10;tokens=Math.min(50,tokens+rate*0.5);if(tokens>=1){tokens--;reqs.push('ok');}else{reqs.push('shed');}}
var shed=reqs.filter(function(r){return r==='shed';}).length;
console.log('technique: Circuit Breaker Tripping');console.log('requests: '+reqs.length+', admitted: '+(reqs.length-shed)+', shed: '+shed);
console.log('shed rate: '+(100*shed/reqs.length).toFixed(1)+'% — excess load dropped with 429, core traffic protected');

