// Demo: Request Hedging — deadline-aware dropping
var now=1000,done=0,dropped=0;
for(var i=0;i<31;i++){var deadline=now+((i*53+5)%400)-100;var cost=20+((i*17)%60);if(deadline<now+cost){dropped++;}else{done++;now+=cost;}}
